<script>
"use strict";

/* ============================================================
   GALAGA — single-file clone
   Logical playfield: 224 x 288 (arcade proportions)
   ============================================================ */

const W = 224, H = 288;

// ---------- Canvas setup ----------
const canvas = document.getElementById("c");
const ctx = canvas.getContext("2d");
ctx.imageSmoothingEnabled = false;

function resize() {
  const scale = Math.max(1, Math.floor(Math.min(window.innerWidth / W, window.innerHeight / H)));
  canvas.style.width = (W * scale) + "px";
  canvas.style.height = (H * scale) + "px";
}
window.addEventListener("resize", resize);
resize();

// ---------- Audio (Web Audio API) ----------
const Audio = {
  ctx: null,
  muted: false,
  ensure() {
    if (!this.ctx) {
      try {
        this.ctx = new (window.AudioContext || window.webkitAudioContext)();
      } catch (e) { this.ctx = null; }
    }
    if (this.ctx && this.ctx.state === "suspended") this.ctx.resume();
  },
  tone(freq, dur, type, vol, slideTo) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type || "square";
    o.frequency.setValueAtTime(freq, t);
    if (slideTo) o.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), t + dur);
    g.gain.setValueAtTime(vol || 0.15, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(this.ctx.destination);
    o.start(t); o.stop(t + dur + 0.02);
  },
  noise(dur, vol) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    const n = Math.floor(this.ctx.sampleRate * dur);
    const buf = this.ctx.createBuffer(1, n, this.ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < n; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / n);
    const s = this.ctx.createBufferSource();
    s.buffer = buf;
    const g = this.ctx.createGain();
    g.gain.value = vol || 0.2;
    s.connect(g); g.connect(this.ctx.destination);
    s.start(t);
  },
  playerShot() { this.tone(900, 0.08, "square", 0.12, 400); },
  enemyHit()   { this.tone(600, 0.06, "square", 0.10, 300); },
  enemyDie()   { this.noise(0.18, 0.18); this.tone(300, 0.15, "sawtooth", 0.08, 80); },
  bossHit()    { this.tone(500, 0.09, "square", 0.12, 250); },
  playerDie()  { this.noise(0.35, 0.25); this.tone(200, 0.35, "sawtooth", 0.12, 40); },
  beam()       { this.tone(180, 0.25, "sine", 0.10, 600); },
  stageStart() {
    const notes = [523, 659, 784, 1047];
    notes.forEach((f, i) => {
      setTimeout(() => this.tone(f, 0.12, "square", 0.10), i * 90);
    });
  },
  extraShip() { this.tone(800, 0.1, "square", 0.1); setTimeout(()=>this.tone(1200,0.15,"square",0.1),100); }
};

// ---------- Sprite data (pixel art) ----------
// Each sprite: array of strings, characters map to palette colors.
// '.' = transparent
const PAL = {
  'W': '#ffffff',
  'B': '#2b6fff',   // blue
  'Y': '#ffe23a',   // yellow
  'R': '#ff3a3a',   // red
  'G': '#3aff6b',   // green
  'P': '#b05cff',   // purple
  'C': '#7fd8ff',   // cyan
  'O': '#ff9a2b',   // orange
  'K': '#222222',
};

// Zako (blue/yellow bee) — 2 frames
const ZAKO = [
  [
    "..Y....Y..",
    ".YYBBBBYY.",
    "YBBBBBBBBY",
    ".BBYBBYBB.",
    ".BBBBBBBB.",
    "..BBBBBB..",
    "...BBBB...",
