    ".Y......Y."
  ],
  [
    "..Y....Y..",
    ".YYBBBBYY.",
    "YBBBBBBBBY",
    ".BBYBBYBB.",
    ".BBBBBBBB.",
    "..BBBBBB..",
    "...BBBB...",
    "...Y..Y...",
    "..Y....Y.."
  ]
];

// Goei (red butterfly) — 2 frames
const GOEI = [
  [
    "..R....R..",
    ".RRRRRRRR.",
    "RRRRRRRRRR",
    ".RRRRRRRR.",
    ".RR.RR.RR.",
    "..RRRRRR..",
    "...RRRR...",
    "...R..R...",
    "..R....R.."
  ],
  [
    "..R....R..",
    ".RRRRRRRR.",
    "RRRRRRRRRR",
    ".RRRRRRRR.",
    ".RR.RR.RR.",
    "..RRRRRR..",
    "...RRRR...",
    "..R....R..",
    ".R......R."
  ]
];

// Boss Galaga — green (alive) and blue/purple (after first hit)
const BOSS_GREEN = [
  [
    "..GGGGGG..",
    ".GGGGGGGG.",
    "GGGGGGGGGG",
    "GGGGGGGGGG",
    ".GGGGGGGG.",
    "..GGGGGG..",
    "...GGGG...",
    "...G..G...",
    "..G....G.."
  ],
  [
    "..GGGGGG..",
    ".GGGGGGGG.",
    "GGGGGGGGGG",
    "GGGGGGGGGG",
    ".GGGGGGGG.",
    "..GGGGGG..",
    "...GGGG...",
    "..G....G..",
    ".G......G."
  ]
];
const BOSS_HURT = [
  [
    "..PPPPPP..",
    ".PPPPPPPP.",
    "PPPPPPPPPP",
    "PPPPPPPPPP",
    ".PPPPPPPP.",
    "..PPPPPP..",
    "...PPPP...",
    "...P..P...",
    "..P....P.."
  ],
  [
    "..PPPPPP..",
    ".PPPPPPPP.",
    "PPPPPPPPPP",
    "PPPPPPPPPP",
    ".PPPPPPPP.",
    "..PPPPPP..",
    "...PPPP...",
    "..P....P..",
